    await page.goto('https://odoo.boltbook.cn/web/login', { waitUntil: 'networkidle' });
    await page.fill('#login', 'james@amygo.ai');
    await page.fill('#password', '123456');
    await page.click('button[type="submit"]');
    await page.waitForNavigation({ waitUntil: 'networkidle' });

    console.log('Navigating to Sales Orders...');
    // Sales order list view
    await page.goto('https://odoo.boltbook.cn/web#action=343&model=sale.order&view_type=list', { waitUntil: 'networkidle' });
    await page.waitForTimeout(5000); // Wait for data to load

    // Extract total (this is a guess of the selector for the total amount in the list view footer)
    const total = await page.evaluate(() => {
        const cell = document.querySelector('.o_list_number[title="Total"], .o_sale_order_total, [name="amount_total"]');
        return cell ? cell.innerText : 'Unknown';
    });
    console.log('DATA_TOTAL:' + total);

    await page.screenshot({ path: '/tmp/odoo_sales_report.png', fullPage: true });
    console.log('Screenshot saved.');
  } catch (e) {
    console.error(e);
  } finally {
    await browser.close();
  }
})();
