];

orders.forEach((order, i) => {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(30, 275 + (i * 45), 740, 40);
  ctx.fillStyle = '#333333';
  ctx.font = '16px sans-serif';
  ctx.fillText(order.name, 50, 300 + (i * 45));
  ctx.fillText(order.state.toUpperCase(), 300, 300 + (i * 45));
